CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, case_id TEXT NOT NULL, label TEXT, created_at INTEGER NOT NULL, event_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'created', premium INTEGER NOT NULL DEFAULT 0, premium_answer TEXT, duration_min INTEGER NOT NULL DEFAULT 90, vars TEXT NOT NULL, secrets TEXT NOT NULL, join_code TEXT NOT NULL UNIQUE, org_code TEXT NOT NULL UNIQUE, org_token TEXT, test_mode INTEGER NOT NULL DEFAULT 0, opened_at INTEGER, started_at INTEGER, ended_at INTEGER, max_teams INTEGER, logo TEXT, lang TEXT);
CREATE TABLE IF NOT EXISTS teams (id TEXT PRIMARY KEY, session_id TEXT NOT NULL, name TEXT NOT NULL, token TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, core_at INTEGER, solved_at INTEGER, penalty_min INTEGER NOT NULL DEFAULT 0, wrong INTEGER NOT NULL DEFAULT 0, last_attempt_at INTEGER, last_result TEXT, tips TEXT NOT NULL DEFAULT '[]', act2_at INTEGER, view_token TEXT, aria_unlocked_at INTEGER, aria_last_at INTEGER, bonus TEXT, bonus_min INTEGER NOT NULL DEFAULT 0, bonus_done_at INTEGER, login_fails INTEGER NOT NULL DEFAULT 0, UNIQUE (session_id, name));
CREATE TABLE IF NOT EXISTS attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, team_id TEXT NOT NULL, at INTEGER NOT NULL, payload TEXT NOT NULL, correct INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS viewers (token TEXT PRIMARY KEY, team_id TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_teams_session ON teams(session_id);
CREATE INDEX IF NOT EXISTS idx_attempts_team ON attempts(team_id);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, token TEXT NOT NULL, created_at INTEGER NOT NULL, status TEXT NOT NULL, paket TEXT NOT NULL, teams INTEGER NOT NULL, amount_cents INTEGER NOT NULL, event_date TEXT NOT NULL, vars TEXT NOT NULL, contact TEXT NOT NULL, logo TEXT, stripe_session TEXT, session_id TEXT, paid_at INTEGER, shipped_at INTEGER, feedback_token TEXT, feedback_sent_at INTEGER);
CREATE TABLE IF NOT EXISTS stats_teams (session_id TEXT NOT NULL, team_no INTEGER NOT NULL, recorded_at INTEGER NOT NULL, case_id TEXT, premium INTEGER, test_mode INTEGER, duration_min INTEGER, teams_in_round INTEGER, stage_reached INTEGER, core_min REAL, act2_min REAL, solved_min REAL, attempts INTEGER, wrong INTEGER, penalty_min INTEGER, wrong_by_q TEXT, hints_akt1 INTEGER, hints_akt2 INTEGER, viewers INTEGER, PRIMARY KEY (session_id, team_no));
CREATE TABLE IF NOT EXISTS aria_msgs (id INTEGER PRIMARY KEY AUTOINCREMENT, team_id TEXT NOT NULL, at INTEGER NOT NULL, role TEXT NOT NULL, text TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS feedback (id TEXT PRIMARY KEY, order_id TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, variant TEXT NOT NULL, lang TEXT, paket TEXT, rating INTEGER, nps INTEGER, answers TEXT, review TEXT, publish TEXT NOT NULL DEFAULT 'no', publish_name TEXT, approved INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS cost_items (id TEXT PRIMARY KEY, name TEXT NOT NULL, anbieter TEXT, art TEXT NOT NULL, betrag_cents INTEGER, waehrung TEXT NOT NULL DEFAULT 'EUR', anteil INTEGER, seit TEXT, beleg TEXT, hinweis TEXT, sort INTEGER NOT NULL DEFAULT 0, deleted INTEGER NOT NULL DEFAULT 0, updated_at INTEGER);
CREATE TABLE IF NOT EXISTS nl_contacts (email TEXT PRIMARY KEY, lang TEXT NOT NULL DEFAULT 'de', name TEXT, source TEXT NOT NULL, status TEXT NOT NULL, token TEXT NOT NULL, created_at INTEGER NOT NULL, confirmed_at INTEGER, consent TEXT, unsub_at INTEGER, synced_at INTEGER, sync_error TEXT);
CREATE TABLE IF NOT EXISTS nl_ecg (h TEXT PRIMARY KEY, v INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS nl_settings (k TEXT PRIMARY KEY, v TEXT);
CREATE TABLE IF NOT EXISTS nl_visits (tag TEXT NOT NULL, day TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (tag, day));
CREATE TABLE IF NOT EXISTS nl_drafts (id TEXT PRIMARY KEY, tag TEXT NOT NULL, lang TEXT NOT NULL, subject TEXT NOT NULL, broadcast_id TEXT, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS nl_contacts_token ON nl_contacts (token);
CREATE TABLE IF NOT EXISTS expenses (id TEXT PRIMARY KEY, datum TEXT NOT NULL, bezahlt_am TEXT, anbieter TEXT NOT NULL, beschreibung TEXT, kategorie TEXT, steuerart TEXT NOT NULL, betrag_cents INTEGER NOT NULL, ust_cents INTEGER, orig TEXT, anteil INTEGER NOT NULL DEFAULT 100, bezahlt_von TEXT NOT NULL DEFAULT 'konto', beleg TEXT, notiz TEXT, cost_id TEXT, dup_ok INTEGER NOT NULL DEFAULT 0, bank_ref TEXT, created_at INTEGER NOT NULL, updated_at INTEGER, deleted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS rc_paid (quartal TEXT PRIMARY KEY, paid_at INTEGER);
CREATE TABLE IF NOT EXISTS duties_done (key TEXT PRIMARY KEY, done_at INTEGER);
CREATE TABLE IF NOT EXISTS expense_files (id TEXT PRIMARY KEY, expense_id TEXT NOT NULL, name TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, r2_key TEXT NOT NULL, created_at INTEGER NOT NULL, deleted INTEGER NOT NULL DEFAULT 0);
